import{_ as s,c as t,o as i,j as n,Y as o,t as r}from"./chunks/framework.BNTND4LZ.js";const k=JSON.parse('{"title":"mailaddr | x-cmd man (man7) | mail addressing description","titleTemplate":false,"description":"x-cmd man (man7 Manual Page) | mailaddr - mail addressing description","frontmatter":{"pageClass":"x-man","head":[["meta",{"name":"og:title","content":"mailaddr | x-cmd man (man7) | mail addressing description"}],["meta",{"name":"og:description","content":"x-cmd man (man7 Manual Page) | mailaddr - mail addressing description"}]]},"headers":[],"params":{"isMan":true,"man":"mailaddr","category":"man7","desc":"mail addressing description"},"relativePath":"man7/mailaddr.md","filePath":"man7/[man].md"}'),h={name:"man7/mailaddr.md"},l={class:"visually-hidden"};function d(e,a,p,m,c,u){return i(),t("div",null,[n("h1",l,r(e.$params.man),1),a[0]||(a[0]=o(`<h2 id="name" tabindex="-1">NAME <a class="header-anchor" href="#name" aria-label="Permalink to &quot;NAME&quot;">​</a></h2><p>mailaddr - mail addressing description</p><h2 id="description" tabindex="-1">DESCRIPTION <a class="header-anchor" href="#description" aria-label="Permalink to &quot;DESCRIPTION&quot;">​</a></h2><p>This manual page gives a brief introduction to SMTP mail addresses, as used on the Internet. These addresses are in the general format</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">user@domain</span></span></code></pre></div><p>where a domain is a hierarchical dot-separated list of subdomains. These examples are valid forms of the same address:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">john.doe@monet.example.com</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">John</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Doe</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">john.doe@monet.example.co</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">m</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">john.doe@monet.example.com</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (John </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">Doe</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div><p>The domain part (&quot;monet.example.com&quot;) is a mail-accepting domain. It can be a host and in the past it usually was, but it doesn&#39;t have to be. The domain part is not case sensitive.</p><p>The local part (&quot;john.doe&quot;) is often a username, but its meaning is defined by the local software. Sometimes it is case sensitive, although that is unusual. If you see a local-part that looks like garbage, it is usually because of a gateway between an internal e-mail system and the net, here are some examples:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">&quot;surname/admd=telemail/c=us/o=hp/prmd=hp&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">@some.where</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">USER%SOMETHING@some.where</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">machine!machine!name@some.where</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">I2461572@some.where</span></span></code></pre></div><p>(These are, respectively, an X.400 gateway, a gateway to an arbitrary internal mail system that lacks proper internet support, an UUCP gateway, and the last one is just boring username policy.)</p><p>The real-name part (&quot;John Doe&quot;) can either be placed before &lt;&gt;, or in () at the end. (Strictly speaking the two aren&#39;t the same, but the difference is beyond the scope of this page.) The name may have to be quoted using &quot;&quot;, for example, if it contains &quot;.&quot;:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">&quot;John Q. Doe&quot;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">john.doe@monet.example.co</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">m</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span></code></pre></div><h3 id="abbreviation" tabindex="-1">Abbreviation <a class="header-anchor" href="#abbreviation" aria-label="Permalink to &quot;Abbreviation&quot;">​</a></h3><p>Some mail systems let users abbreviate the domain name. For instance, users at example.com may get away with &quot;john.doe@monet&quot; to send mail to John Doe. <em>This behavior is deprecated.</em> Sometimes it works, but you should not depend on it.</p><h3 id="route-addrs" tabindex="-1">Route-addrs <a class="header-anchor" href="#route-addrs" aria-label="Permalink to &quot;Route-addrs&quot;">​</a></h3><p>In the past, sometimes one had to route a message through several hosts to get it to its final destination. Addresses which show these relays are termed &quot;route-addrs&quot;. These use the syntax:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">@hosta,@hostb:user@hostc</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span></code></pre></div><p>This specifies that the message should be sent to hosta, from there to hostb, and finally to hostc. Many hosts disregard route-addrs and send directly to hostc.</p><p>Route-addrs are very unusual now. They occur sometimes in old mail archives. It is generally possible to ignore all but the &quot;user@hostc&quot; part of the address to determine the actual address.</p><h3 id="postmaster" tabindex="-1">Postmaster <a class="header-anchor" href="#postmaster" aria-label="Permalink to &quot;Postmaster&quot;">​</a></h3><p>Every site is required to have a user or user alias designated &quot;postmaster&quot; to which problems with the mail system may be addressed. The &quot;postmaster&quot; address is not case sensitive.</p><h2 id="files" tabindex="-1">FILES <a class="header-anchor" href="#files" aria-label="Permalink to &quot;FILES&quot;">​</a></h2><p><em>/etc/aliases</em> <br> <em>~/.forward</em></p><h2 id="see-also" tabindex="-1">SEE ALSO <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;SEE ALSO&quot;">​</a></h2><p><strong>mail</strong>(1), <strong>aliases</strong>(5), <strong>forward</strong>(5), <strong>sendmail</strong>(8)</p><p><a href="http://www.ietf.org/rfc/rfc5322.txt" target="_blank" rel="noreferrer">IETF RFC 5322</a></p>`,27))])}const b=s(h,[["render",d]]);export{k as __pageData,b as default};
